{
  "diagnosis": "Recurring failures come from three generalizable causes: (1) option_selection prefers the more familiar or dialogue-mentioned drug over the option with better indication fit for the stated condition, even when the other option is less appropriate or less safe; (2) safety_check treats an unmentioned interaction or contraindication as if it were established and either withholds an appropriate drug or invents risk, rather than resolving only stated facts; (3) patient_evidence frequently misses key stated constraints such as current medication use, symptom timing, pregnancy history, or activity/exposure history because it does not force retrieval of exact patient statements. Prior evidence also overstates distinctions that are not explicit in the dialogue. These are mechanism-level causes, not case answers.",
  "skills": [
    {
      "id": "indication_first_selection",
      "text": "When selecting a medication, first map the stated diagnosis or syndrome to the option whose mechanism and indication most directly treat that condition. Do not let a drug that is merely named in the dialogue, or that is more familiar, override a better-indicated option unless the dialogue establishes a patient-specific reason to avoid it."
    },
    {
      "id": "explicit_constraint_resolution",
      "text": "Before excluding an appropriate option, require an explicit stated contraindication, allergy, or interaction. If the patient fact is missing, do not invent it; if a potential concern is only hypothesized by the clinician, treat it as a prompt for monitoring rather than as a confirmed reason to choose a worse-indicated drug."
    },
    {
      "id": "retrieve_exact_patient_facts",
      "text": "Extract exact patient statements for current medicines, symptom duration and triggers, pregnancy or gestational history, recent travel or exposure, and prior diagnoses. Use these excerpts to constrain both indication and safety rather than relying on general impressions."
    },
    {
      "id": "compare_within_class",
      "text": "When multiple options belong to the same class or related mechanism, compare them by formulation, indication, route, and patient-specific interaction profile. Do not assume that two similar drugs are interchangeable; choose the one that best matches the stated clinical problem and avoids the stated risks."
    },
    {
      "id": "avoid_reference_position_bias",
      "text": "Do not encode or use benchmark-position, answer-letter, or case-specific shortcuts. Generalize from the mechanism of action, labeled indication, and stated patient facts only."
    }
  ],
  "focus_terms": [
    "I'm currently taking",
    "I've been taking",
    "diagnosed with",
    "history of",
    "during my last pregnancy",
    "I visited",
    "exposure to",
    "started about",
    "come and go",
    "after physical activities",
    "before my workout",
    "I use an inhaler",
    "family history of",
    "currently under control",
    "seem to worsen when",
    "more often when I take"
  ],
  "modules": {
    "patient_evidence": "Extract exact dialogue statements about the stated condition, current medicines, symptom onset and triggers, pregnancy/gestational history, recent travel or environmental exposure, allergies, and relevant family history. Preserve the patient's wording as evidence, and do not infer absent facts.",
    "safety_check": "Only use explicitly stated contraindications, allergies, or interactions. If the dialogue does not establish a safety problem, do not treat the option as unsafe. When a possible interaction is raised but not confirmed, note it as a monitoring issue rather than a reason to eliminate an otherwise indicated option.",
    "option_selection": "Rank options by fit to the stated diagnosis and patient-specific facts. Prefer the option whose indication and mechanism most directly address the active problem, unless an explicit stated contraindication or interaction rules it out. Do not select based on dialogue mention, familiarity, or benchmark position."
  }
}
